// ---- Circuit (Kit 4) ----
// HC-SR04: VCC 5V, GND, TRIG -> D9, ECHO -> D10
#define TRIG 9
#define ECHO 10

float distCm() {                           // HC-SR04: 10 us trigger pulse, echo time / 58 = cm (-1 = no echo)
  digitalWrite(TRIG, LOW); delayMicroseconds(2);
  digitalWrite(TRIG, HIGH); delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long us = pulseIn(ECHO, HIGH, 30000);
  if (us == 0) return -1;
  return us / 58.2;
}
void usBegin() { pinMode(TRIG, OUTPUT); pinMode(ECHO, INPUT); }

void setup() {
  Serial.begin(9600);
  usBegin();
}

void loop() {
  float cm = distCm();
  if (cm < 0) Serial.println("no echo (out of range)");
  else { Serial.print("Distance: "); Serial.print(cm, 1); Serial.println(" cm"); }
  delay(400);
}

// ---- Circuit (Kit 4) ----
// PIR HC-SR501: VCC 5V, GND, OUT -> D7 (HIGH while it sees motion)
// Red LED anode -> 220 ohm -> D3, cathode -> GND
#define PIR_PIN 7
#define RED_LED 3

void setup() {
  pinMode(PIR_PIN, INPUT);
  pinMode(RED_LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  bool motion = digitalRead(PIR_PIN) == HIGH;
  digitalWrite(RED_LED, motion);
  Serial.println(motion ? "motion!" : "quiet");
  delay(300);
}

// ---- Circuit (Kit 4) ----
// IR obstacle sensor: VCC 5V, GND, OUT -> D8 (LOW when something is in front)
// Red LED anode -> 220 ohm -> D3, cathode -> GND
#define IR_PIN 8
#define RED_LED 3

void setup() {
  pinMode(IR_PIN, INPUT);
  pinMode(RED_LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  bool blocked = digitalRead(IR_PIN) == LOW;               // the module pulls OUT LOW when it sees a reflection
  digitalWrite(RED_LED, blocked);
  Serial.println(blocked ? "obstacle ahead" : "path clear");
  delay(250);
}

// ---- Circuit (Kit 4) ----
// TTP223 touch pad: VCC 5V, GND, I/O -> D4 (HIGH while touched)
// Green LED anode -> 220 ohm -> D5 (PWM), cathode -> GND
#define TOUCH_PIN 4
#define GREEN_LED 5

bool lampOn = false;
int lastTouch = LOW;

void setup() {
  pinMode(TOUCH_PIN, INPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int t = digitalRead(TOUCH_PIN);
  if (t == HIGH && lastTouch == LOW) {                      // new touch
    lampOn = !lampOn;
    digitalWrite(GREEN_LED, lampOn);
    Serial.println(lampOn ? "lamp ON" : "lamp OFF");
  }
  lastTouch = t;
  delay(30);
}

// ---- Circuit (Kit 4) ----
// A3144 Hall sensor: VCC 5V, GND, OUT -> D12 (INPUT_PULLUP, LOW when a magnet is near)
// Red LED anode -> 220 ohm -> D3, cathode -> GND
#define HALL_PIN 12
#define RED_LED 3

void setup() {
  pinMode(HALL_PIN, INPUT_PULLUP);                          // the A3144 is open-collector: it needs a pull-up
  pinMode(RED_LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  bool magnet = digitalRead(HALL_PIN) == LOW;
  digitalWrite(RED_LED, magnet);
  Serial.println(magnet ? "magnet near - door CLOSED" : "no magnet - door OPEN");
  delay(300);
}

// ---- Circuit (Kit 4) ----
