#define ARM_DELAY_MS 5000
int state = 0;                              // 0 disarmed, 1 arming, 2 armed, 3 alarm
unsigned long armStart = 0;

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(PIR_PIN, INPUT);
  pinMode(RED_LED, OUTPUT);
  Serial.begin(9600);
  Serial.println("DISARMED - press the button to arm");
}

void loop() {
  if (pressed()) {
    if (state == 0) { state = 1; armStart = millis(); Serial.println("arming... leave the room"); }
    else { state = 0; noTone(BUZZER); digitalWrite(RED_LED, LOW); Serial.println("DISARMED"); }
  }
  if (state == 1) {
    digitalWrite(RED_LED, (millis() / 100) % 2);
    if (millis() - armStart >= ARM_DELAY_MS) { state = 2; Serial.println("ARMED"); }
  } else if (state == 2) {
    digitalWrite(RED_LED, HIGH);
    if (digitalRead(PIR_PIN) == HIGH) { state = 3; Serial.println("INTRUDER DETECTED!"); }
  } else if (state == 3) {
    tone(BUZZER, (millis() / 300) % 2 ? 1400 : 800);         // two-tone siren
    digitalWrite(RED_LED, (millis() / 150) % 2);
  }
}

