// ---- Circuit (Kit 4) ----
// A3144 Hall sensor: VCC 5V, GND, OUT -> D12 (INPUT_PULLUP, LOW when a magnet is near)
// Passive piezo buzzer + -> D11, - -> GND (drive it with tone())
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// Green LED anode -> 220 ohm -> D5 (PWM), cathode -> GND
#define HALL_PIN 12
#define BUZZER 11
#define RED_LED 3
#define GREEN_LED 5

bool closed = true;
unsigned long changedAt = 0, lastBeep = 0;

void setup() {
  pinMode(HALL_PIN, INPUT_PULLUP);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
  closed = digitalRead(HALL_PIN) == LOW;
  Serial.println(closed ? "log started: door CLOSED" : "log started: door OPEN");
}

void loop() {
  bool c = digitalRead(HALL_PIN) == LOW;                    // magnet near = door closed
  if (c != closed) {
    unsigned long dur = (millis() - changedAt) / 1000;
    closed = c;
    changedAt = millis();
    Serial.print("[t="); Serial.print(millis() / 1000); Serial.print(" s] door ");
    if (closed) { Serial.print("CLOSED (was open "); Serial.print(dur); Serial.println(" s)"); }
    else Serial.println("OPENED");
  }
  digitalWrite(GREEN_LED, closed);
  digitalWrite(RED_LED, !closed);
  if (!closed && millis() - changedAt > 5000 && millis() - lastBeep > 1000) {   // left open too long
    lastBeep = millis();
    tone(BUZZER, 1500, 200);
  }
}

// ---- Circuit (Kit 4) ----
// HC-SR04: VCC 5V, GND, TRIG -> D9, ECHO -> D10
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// Green LED anode -> 220 ohm -> D5 (PWM), cathode -> GND
#define TRIG 9
#define ECHO 10
#define RED_LED 3
#define GREEN_LED 5

float distCm() {                           // HC-SR04: 10 us trigger pulse, echo time / 58 = cm (-1 = no echo)
  digitalWrite(TRIG, LOW); delayMicroseconds(2);
  digitalWrite(TRIG, HIGH); delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long us = pulseIn(ECHO, HIGH, 30000);
  if (us == 0) return -1;
  return us / 58.2;
}
void usBegin() { pinMode(TRIG, OUTPUT); pinMode(ECHO, INPUT); }

#define SENSOR_TO_BOTTOM 35.0                   // cm from the sensor down to the tank floor (30 cm tank + 5 cm gap)
#define TANK_HEIGHT 30.0

void setup() {
  usBegin();
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  float cm = distCm();
  if (cm < 0) { Serial.println("no echo"); delay(300); return; }
  float level = constrain((SENSOR_TO_BOTTOM - cm) * 100.0 / TANK_HEIGHT, 0, 100);
  bool alert = level < 10 || level > 90;
  digitalWrite(RED_LED, alert);
  digitalWrite(GREEN_LED, !alert);
  Serial.print("level "); Serial.print(level, 0); Serial.print(" %  [");
  for (int i = 0; i < 10; i++) Serial.print(i < level / 10 ? "#" : ".");
  Serial.println(alert ? "]  CHECK TANK" : "]");
  delay(400);
}

