long filt = -1;                                // filtered distance in mm (integer maths only)
bool mute = false;
unsigned long lastBeep = 0, lastPrint = 0;

long fusedMm() {
  int tof = tofMm();
  float us = distCm();
  long usMm = us < 0 ? -1 : (long)(us * 10);
  if (tof >= 0 && tof < 1200) {
    if (usMm >= 0 && abs(tof - usMm) < 100) return (tof * 7L + usMm * 3L) / 10;   // both agree: weight the laser 70 %
    return tof;
  }
  return usMm;                                               // ToF out of range: ultrasonic only
}

void setup() {
  usBegin();
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
  tofBegin();
}

void loop() {
  long d = fusedMm();
  if (d < 0) d = 4000;
  filt = (filt < 0) ? d : (filt * 3 + d) / 4;                // new = 3/4 old + 1/4 measurement
  if (pressed()) { mute = !mute; Serial.println(mute ? "buzzer muted" : "buzzer on"); }

  bool stopNow = filt < 150;
  digitalWrite(GREEN_LED, filt > 300);
  if (filt > 600) {
    digitalWrite(RED_LED, LOW); noTone(BUZZER);
  } else if (stopNow) {
    digitalWrite(RED_LED, HIGH);
    if (mute) noTone(BUZZER); else tone(BUZZER, 2500);
  } else {
    int gap = map(filt, 150, 600, 80, 600);
    if (millis() - lastBeep >= gap) { lastBeep = millis(); if (!mute) tone(BUZZER, 2000, 50); }
    digitalWrite(RED_LED, millis() - lastBeep < 60);
  }
  if (millis() - lastPrint > 400) {
    lastPrint = millis();
    Serial.print("distance "); Serial.print(filt); Serial.print(" mm");
    Serial.println(stopNow ? "  STOP!" : (filt > 600 ? "  clear" : "  approaching"));
  }
  delay(25);
}

