// PIR HC-SR501: VCC 5V, GND, OUT -> D7 (HIGH while it sees motion)
// A3144 Hall sensor: VCC 5V, GND, OUT -> D12 (INPUT_PULLUP, LOW when a magnet is near)
// HC-SR04: VCC 5V, GND, TRIG -> D9, ECHO -> D10
// TTP223 touch pad: VCC 5V, GND, I/O -> D4 (HIGH while touched)
// Passive piezo buzzer + -> D11, - -> GND (drive it with tone())
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// Green LED anode -> 220 ohm -> D5 (PWM), cathode -> GND
#define PIR_PIN 7
#define HALL_PIN 12
#define TRIG 9
#define ECHO 10
#define TOUCH_PIN 4
#define BUZZER 11
#define RED_LED 3
#define GREEN_LED 5

float distCm() {                           // HC-SR04: 10 us trigger pulse, echo time / 58 = cm (-1 = no echo)
  digitalWrite(TRIG, LOW); delayMicroseconds(2);
  digitalWrite(TRIG, HIGH); delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long us = pulseIn(ECHO, HIGH, 30000);
  if (us == 0) return -1;
  return us / 58.2;
}
void usBegin() { pinMode(TRIG, OUTPUT); pinMode(ECHO, INPUT); }

#define EXIT_MS 8000
#define ENTRY_MS 8000
#define CODE "SLS"                              // short, long (>= 0.5 s), short

int state = 0;                                  // 0 disarmed, 1 exit delay, 2 armed, 3 entry delay, 4 alarm
unsigned long stateAt = 0, touchStart = 0, lastTap = 0;
bool touching = false;
String entered = "";

void setState(int s, String msg) {
  state = s; stateAt = millis();
  Serial.println(msg);
}

void toggleArm() {
  if (state == 0) setState(1, "arming - leave now (exit delay)");
  else { noTone(BUZZER); setState(0, "DISARMED"); }
}

void readTouchCode() {
  int t = digitalRead(TOUCH_PIN);
  if (t == HIGH && !touching) { touching = true; touchStart = millis(); }
  if (t == LOW && touching) {
    touching = false;
    if (millis() - touchStart >= 500) entered += "L"; else entered += "S";
    lastTap = millis();
    Serial.print("code so far: "); Serial.println(entered);
    if (entered.length() > 3) entered = entered.substring(entered.length() - 3);
    if (entered == CODE) { entered = ""; toggleArm(); }
  }
  if (entered.length() > 0 && millis() - lastTap > 3000) { entered = ""; Serial.println("code timed out"); }
}

void setup() {
  usBegin();
  pinMode(PIR_PIN, INPUT);
  pinMode(HALL_PIN, INPUT_PULLUP);
  pinMode(TOUCH_PIN, INPUT);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
  Serial.println("DISARMED - tap the pad short-long-short to arm");
}

void loop() {
  readTouchCode();
  bool doorOpen = digitalRead(HALL_PIN) == HIGH;             // magnet moved away from the sensor
  float cm = distCm();
  bool room = digitalRead(PIR_PIN) == HIGH || (cm > 0 && cm < 80);

  if (state == 1 && millis() - stateAt >= EXIT_MS) setState(2, "ARMED");
  if (state == 2) {
    if (doorOpen) setState(3, "door opened - enter the code within 8 s");
    else if (room) setState(4, "ALARM: movement in the room");
  }
  if (state == 3 && millis() - stateAt >= ENTRY_MS) setState(4, "ALARM: entry delay expired");

  digitalWrite(GREEN_LED, state == 0);
  if (state == 0) { digitalWrite(RED_LED, LOW); noTone(BUZZER); }
  if (state == 1) digitalWrite(RED_LED, (millis() / 250) % 2);
  if (state == 2) digitalWrite(RED_LED, HIGH);
  if (state == 3) {
    digitalWrite(RED_LED, (millis() / 100) % 2);
    if ((millis() / 1000) % 2 == 0) tone(BUZZER, 1000); else noTone(BUZZER);
  }
  if (state == 4) {
    tone(BUZZER, (millis() / 300) % 2 ? 1500 : 900);
    digitalWrite(RED_LED, (millis() / 120) % 2);
  }
  delay(20);
}

// ---- Circuit (Kit 4) ----
// A3144 Hall sensor: VCC 5V, GND, OUT -> D12 (INPUT_PULLUP, LOW when a magnet is near)
// SG90 servo: signal -> D6, red -> 5V, brown -> GND
// IR obstacle sensor: VCC 5V, GND, OUT -> D8 (LOW when something is in front)
// HC-SR04: VCC 5V, GND, TRIG -> D9, ECHO -> D10
// Green LED anode -> 220 ohm -> D5 (PWM), cathode -> GND
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// Passive piezo buzzer + -> D11, - -> GND (drive it with tone())
#define HALL_PIN 12
#define SERVO_PIN 6
#define IR_PIN 8
#define TRIG 9
#define ECHO 10
#define GREEN_LED 5
#define RED_LED 3
#define BUZZER 11

#include <Servo.h>
Servo servo;
float distCm() {                           // HC-SR04: 10 us trigger pulse, echo time / 58 = cm (-1 = no echo)
  digitalWrite(TRIG, LOW); delayMicroseconds(2);
  digitalWrite(TRIG, HIGH); delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long us = pulseIn(ECHO, HIGH, 30000);
  if (us == 0) return -1;
  return us / 58.2;
}
void usBegin() { pinMode(TRIG, OUTPUT); pinMode(ECHO, INPUT); }

int state = 0;                                  // 0 closed, 1 opening, 2 open, 3 closing
int angle = 0;
unsigned long lastClear = 0, lastStep = 0, lastBeep = 0;

void setState(int s, String msg) { state = s; Serial.println(msg); }

void setup() {
  usBegin();
  pinMode(IR_PIN, INPUT);
  pinMode(HALL_PIN, INPUT_PULLUP);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  servo.attach(SERVO_PIN);
  servo.write(0);
  Serial.begin(9600);
  if (digitalRead(HALL_PIN) != LOW) Serial.println("warning: closed-limit magnet not detected");
  Serial.println("gate CLOSED");
}

void loop() {
  float cm = distCm();
  bool vehicle = cm > 0 && cm < 40;
  bool blocked = digitalRead(IR_PIN) == LOW;                 // something in the gateway
  bool roadBusy = vehicle || blocked || (cm > 0 && cm < 60);

  if (state == 0 && vehicle) setState(1, "vehicle detected - OPENING");
  if (state == 3 && (blocked || vehicle)) { setState(1, "obstacle in the gateway - re-opening!"); tone(BUZZER, 2000, 400); }
  if (state == 2) {
    if (roadBusy) lastClear = millis();
    else if (millis() - lastClear > 4000) setState(3, "road clear - CLOSING");
  }
  if ((state == 1 || state == 3) && millis() - lastStep >= 15) {
    lastStep = millis();
    angle += (state == 1) ? 2 : -2;
    angle = constrain(angle, 0, 90);
    servo.write(angle);
    if (millis() - lastBeep > 500) { lastBeep = millis(); tone(BUZZER, 1200, 80); }   // warning beep while moving
    if (state == 1 && angle >= 90) { setState(2, "gate OPEN"); lastClear = millis(); }
    if (state == 3 && angle <= 0) {
      if (digitalRead(HALL_PIN) == LOW) setState(0, "gate CLOSED (limit magnet confirmed)");
      else setState(0, "gate CLOSED (warning: limit magnet not seen)");
    }
  }
  digitalWrite(GREEN_LED, state == 2);
  digitalWrite(RED_LED, state == 0 ? HIGH : ((millis() / 200) % 2 && state != 2));
  delay(10);
}

// ---- Circuit (Kit 4) ----
// TCRT5000: VCC 5V, GND, DO -> D13 (HIGH over a dark surface / no surface), AO -> A0 (higher = darker)
// SG90 servo: signal -> D6, red -> 5V, brown -> GND
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
// Green LED anode -> 220 ohm -> D5 (PWM), cathode -> GND
// Red LED anode -> 220 ohm -> D3, cathode -> GND
#define LINE_DO 13
#define LINE_AO A0
#define SERVO_PIN 6
#define BTN1 2
#define GREEN_LED 5
#define RED_LED 3

#include <Servo.h>
Servo servo;
int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

int whiteV = 205, blackV = 920, calStep = 0;
float prevErr = 0, sumErr = 0;
unsigned long lastPrint = 0;

#define KP 0.45
#define KI 0.01
#define KD 0.25

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  servo.attach(SERVO_PIN);
  servo.write(90);
  Serial.begin(9600);
  Serial.println("press over WHITE, then over BLACK to calibrate");
}

void loop() {
  int v = analogRead(LINE_AO);
  if (pressed()) {
    if (calStep == 0) { whiteV = v; calStep = 1; Serial.print("white = "); Serial.println(v); }
    else { blackV = v; calStep = 0; Serial.print("black = "); Serial.println(v); }
  }
  float target = (whiteV + blackV) / 2.0;                    // the edge of the line is half way between white and black
  float half = (blackV - whiteV) / 2.0;
  float err = (v - target) * 100.0 / half;                   // -100 (white) .. +100 (black)
  sumErr = constrain(sumErr + err, -500, 500);
  float out = KP * err + KI * sumErr + KD * (err - prevErr);
  prevErr = err;
  int steer = constrain(90 + (int)out, 45, 135);
  servo.write(steer);
  digitalWrite(GREEN_LED, abs(err) < 25);
  digitalWrite(RED_LED, abs(err) > 90);                      // fully white or fully black: line lost
  if (millis() - lastPrint > 250) {
    lastPrint = millis();
    Serial.print("sensor "); Serial.print(v); Serial.print("  error "); Serial.print(err, 0); Serial.print("  steering "); Serial.println(steer);
  }
  delay(20);
}

// ---- Circuit (Kit 4) ----
// SG90 servo: signal -> D6, red -> 5V, brown -> GND
// HC-SR04: VCC 5V, GND, TRIG -> D9, ECHO -> D10
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// Green LED anode -> 220 ohm -> D5 (PWM), cathode -> GND
// Passive piezo buzzer + -> D11, - -> GND (drive it with tone())
#define SERVO_PIN 6
#define TRIG 9
#define ECHO 10
#define RED_LED 3
#define GREEN_LED 5
#define BUZZER 11

#include <Servo.h>
Servo servo;
float distCm() {                           // HC-SR04: 10 us trigger pulse, echo time / 58 = cm (-1 = no echo)
  digitalWrite(TRIG, LOW); delayMicroseconds(2);
  digitalWrite(TRIG, HIGH); delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long us = pulseIn(ECHO, HIGH, 30000);
  if (us == 0) return -1;
  return us / 58.2;
}
void usBegin() { pinMode(TRIG, OUTPUT); pinMode(ECHO, INPUT); }

int ANGLES[5] = {0, 45, 90, 135, 180};
int dist[5];

void setup() {
  usBegin();
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  servo.attach(SERVO_PIN);
  Serial.begin(9600);
}

void loop() {
  for (int i = 0; i < 5; i++) {
    servo.write(ANGLES[i]);
    delay(350);                                              // wait for the servo to arrive
    float cm = distCm();
    dist[i] = (cm < 0) ? 400 : (int)cm;
  }
  int best = 0;
  for (int i = 1; i < 5; i++) if (dist[i] > dist[best]) best = i;
  Serial.print("scan: ");
  for (int i = 0; i < 5; i++) { Serial.print(ANGLES[i]); Serial.print("deg="); Serial.print(dist[i]); Serial.print("  "); }
  Serial.println();

  digitalWrite(GREEN_LED, LOW);
  digitalWrite(RED_LED, LOW);
  if (dist[best] < 20) {
    Serial.println("decision: BLOCKED - STOP");
    digitalWrite(RED_LED, HIGH);
    for (int k = 0; k < 3; k++) { tone(BUZZER, 1800, 150); delay(250); }
  } else if (best == 2) {
    Serial.println("decision: FORWARD");
    digitalWrite(GREEN_LED, HIGH);
    delay(1200);
  } else if (best > 2) {
    Serial.println(best == 4 ? "decision: hard LEFT" : "decision: LEFT");
    digitalWrite(RED_LED, HIGH);
    delay(1200);
  } else {
    Serial.println(best == 0 ? "decision: hard RIGHT" : "decision: RIGHT");
    for (int k = 0; k < 4; k++) { digitalWrite(RED_LED, HIGH); delay(150); digitalWrite(RED_LED, LOW); delay(150); }
  }
}

// ---- Circuit (Kit 4) ----
// TTP223 touch pad: VCC 5V, GND, I/O -> D4 (HIGH while touched)
// VL53L0X: VIN 5V, GND, SDA -> A4, SCL -> A5 (I2C address 0x29)
// Passive piezo buzzer + -> D11, - -> GND (drive it with tone())
// Green LED anode -> 220 ohm -> D5 (PWM), cathode -> GND
// Red LED anode -> 220 ohm -> D3, cathode -> GND
#define TOUCH_PIN 4
#define BUZZER 11
#define GREEN_LED 5
#define RED_LED 3

#include <Wire.h>
#include <Adafruit_VL53L0X.h>
Adafruit_VL53L0X tof;

int tofMm() {                              // distance in mm (-1 = out of range)
  VL53L0X_RangingMeasurementData_t m;
  tof.rangingTest(&m, false);
  if (m.RangeStatus == 4) return -1;
  return m.RangeMilliMeter;
}
void tofBegin() {
  if (!tof.begin()) { Serial.println("VL53L0X not found - check SDA/SCL"); while (true) { } }
}

int mode = 0, lastTouch = LOW;
unsigned long lastPrint = 0, lastTone = 0;

void setup() {
  pinMode(TOUCH_PIN, INPUT);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
  tofBegin();
  Serial.println("mode 1: green brightness");
}

void loop() {
  int t = digitalRead(TOUCH_PIN);
  if (t == HIGH && lastTouch == LOW) {
    mode = (mode + 1) % 3;
    analogWrite(GREEN_LED, 0); analogWrite(RED_LED, 0);
    for (int i = 0; i <= mode; i++) { tone(BUZZER, 1800, 80); delay(160); }     // confirm: one beep per mode number
    Serial.print("mode "); Serial.println(mode + 1);
  }
  lastTouch = t;

  int mm = tofMm();
  if (mm < 0) mm = 400;
  int value = map(constrain(mm, 50, 400), 50, 400, 100, 0);   // 0..100 %
  if (mode == 0) analogWrite(GREEN_LED, value * 255 / 100);
  if (mode == 1) analogWrite(RED_LED, value * 255 / 100);
  if (mode == 2 && millis() - lastTone > 250) { lastTone = millis(); tone(BUZZER, 200 + value * 10, 120); }
  if (millis() - lastPrint > 400) {
    lastPrint = millis();
    Serial.print("mode "); Serial.print(mode + 1); Serial.print("  value "); Serial.print(value); Serial.println(" %");
  }
  delay(20);
}

