// ---- Circuit (Kit 4) ----
// A3144 Hall sensor: VCC 5V, GND, OUT -> D12 (INPUT_PULLUP, LOW when a magnet is near)
// Passive piezo buzzer + -> D11, - -> GND (drive it with tone())
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// Green LED anode -> 220 ohm -> D5 (PWM), cathode -> GND
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
#define HALL_PIN 12
#define BUZZER 11
#define RED_LED 3
#define GREEN_LED 5
#define BTN1 2

int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

unsigned long periods[5];
int n = 0, slot = 0, lastHall = HIGH, limitIdx = 1;
unsigned long lastEdge = 0, lastPrint = 0;
float rpm = 0;

int limitRpm() { return (limitIdx + 1) * 60; }

void setup() {
  pinMode(HALL_PIN, INPUT_PULLUP);
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
  Serial.println("limit 120 rpm");
}

void loop() {
  int now = digitalRead(HALL_PIN);
  if (lastHall == HIGH && now == LOW) {                      // one revolution
    if (lastEdge > 0) {
      periods[slot] = millis() - lastEdge;
      slot = (slot + 1) % 5;
      if (n < 5) n++;
      unsigned long sum = 0;
      for (int i = 0; i < n; i++) sum += periods[i];
      rpm = 60000.0 / (sum / (float)n);                      // moving average of the last 5 periods
    }
    lastEdge = millis();
  }
  lastHall = now;
  if (millis() - lastEdge > 2500) { rpm = 0; n = 0; slot = 0; lastEdge = 0; }    // stopped
  if (pressed()) { limitIdx = (limitIdx + 1) % 3; Serial.print("limit "); Serial.print(limitRpm()); Serial.println(" rpm"); }

  bool over = rpm > limitRpm();
  digitalWrite(RED_LED, over);
  digitalWrite(GREEN_LED, rpm > 0 && !over);
  if (over) tone(BUZZER, (millis() / 150) % 2 ? 2200 : 1700); else noTone(BUZZER);
  if (millis() - lastPrint > 500) {
    lastPrint = millis();
    Serial.print("rpm "); Serial.print(rpm, 0);
    Serial.println(over ? "  OVERSPEED!" : "");
  }
}

// ---- Circuit (Kit 4) ----
// SG90 servo: signal -> D6, red -> 5V, brown -> GND
// IR obstacle sensor: VCC 5V, GND, OUT -> D8 (LOW when something is in front)
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
// Green LED anode -> 220 ohm -> D5 (PWM), cathode -> GND
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// Passive piezo buzzer + -> D11, - -> GND (drive it with tone())
#define SERVO_PIN 6
#define IR_PIN 8
#define BTN1 2
#define GREEN_LED 5
#define RED_LED 3
#define BUZZER 11

#include <Servo.h>
Servo servo;
int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

int queue[4];
int qLen = 0, floorNow = 0, taps = 0, angle = 0;
unsigned long lastTap = 0;

void enqueue(int f) {
  if (qLen < 4 && f != floorNow) { queue[qLen] = f; qLen++; Serial.print("call queued: floor "); Serial.println(f + 1); }
}

void arrive() {
  floorNow = queue[0];
  for (int i = 1; i < qLen; i++) queue[i - 1] = queue[i];
  qLen--;
  digitalWrite(RED_LED, LOW);
  tone(BUZZER, 1500, 300);
  digitalWrite(GREEN_LED, HIGH);
  Serial.print("arrived at floor "); Serial.println(floorNow + 1);
  unsigned long openAt = millis();
  while (millis() - openAt < 2000 || digitalRead(IR_PIN) == LOW) { delay(20); }   // doors stay open while blocked
  digitalWrite(GREEN_LED, LOW);
  Serial.println("doors closed");
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(IR_PIN, INPUT);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  servo.attach(SERVO_PIN);
  servo.write(0);
  Serial.begin(9600);
  Serial.println("elevator at floor 1 - tap the button 1, 2 or 3 times to call a floor");
}

void loop() {
  if (pressed()) { taps++; lastTap = millis(); }
  if (taps > 0 && millis() - lastTap > 700) {                // taps counted: that is the requested floor
    enqueue(constrain(taps, 1, 3) - 1);
    taps = 0;
  }
  if (qLen > 0) {
    int target = queue[0] * 90;
    digitalWrite(RED_LED, HIGH);
    if (angle < target) angle += 2;
    else if (angle > target) angle -= 2;
    servo.write(angle);
    delay(12);
    if (abs(angle - target) < 2) { angle = target; servo.write(angle); arrive(); }
  }
}

// ---- Circuit (Kit 4) ----
// IR obstacle sensor: VCC 5V, GND, OUT -> D8 (LOW when something is in front)
// TCRT5000: VCC 5V, GND, DO -> D13 (HIGH over a dark surface / no surface), AO -> A0 (higher = darker)
// Passive piezo buzzer + -> D11, - -> GND (drive it with tone())
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// Green LED anode -> 220 ohm -> D5 (PWM), cathode -> GND
#define IR_PIN 8
#define LINE_DO 13
#define LINE_AO A0
#define BUZZER 11
#define RED_LED 3
#define GREEN_LED 5

#define GATE_CM 20.0
#define LIMIT_CMS 40.0                          // speed limit in cm/s

int stage = 0;
unsigned long t1 = 0;

void setup() {
  pinMode(IR_PIN, INPUT);
  pinMode(LINE_DO, INPUT);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
  Serial.println("speed trap armed");
}

void loop() {
  if (stage == 0 && digitalRead(IR_PIN) == LOW) { t1 = millis(); stage = 1; }
  else if (stage == 1) {
    if (digitalRead(LINE_DO) == HIGH) {
      unsigned long dt = millis() - t1;
      float v = GATE_CM * 1000.0 / dt;
      bool speeding = v > LIMIT_CMS;
      Serial.print("speed "); Serial.print(v, 1); Serial.print(" cm/s  ");
      Serial.println(speeding ? "SPEEDING!" : "within the limit");
      digitalWrite(RED_LED, speeding);
      digitalWrite(GREEN_LED, !speeding);
      if (speeding) { tone(BUZZER, 2000, 600); }
      delay(1500);
      digitalWrite(RED_LED, LOW); digitalWrite(GREEN_LED, LOW);
      while (digitalRead(IR_PIN) == LOW || digitalRead(LINE_DO) == HIGH) { }
      stage = 0;
    } else if (millis() - t1 > 5000) { stage = 0; Serial.println("timeout"); }
  }
}

