#define SENSOR_TO_BOTTOM 35.0
#define TANK_HEIGHT 30.0

bool pump = false, alarm = false;
unsigned long pumpWindow = 0, lastPrint = 0;
float levelAtWindow = 0;

float levelPct() {
  float cm = distCm();
  if (cm < 0) return -1;
  return constrain((SENSOR_TO_BOTTOM - cm) * 100.0 / TANK_HEIGHT, 0, 100);
}

void setup() {
  usBegin();
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  float lvl = levelPct();
  if (lvl < 0) { delay(200); return; }
  if (alarm) {
    tone(BUZZER, (millis() / 250) % 2 ? 1500 : 1000);
    digitalWrite(RED_LED, (millis() / 200) % 2);
    if (pressed()) { alarm = false; noTone(BUZZER); digitalWrite(RED_LED, LOW); Serial.println("alarm reset"); }
    return;
  }
  if (!pump && lvl < 25) { pump = true; pumpWindow = millis(); levelAtWindow = lvl; Serial.println("level low - pump ON"); }
  if (pump && lvl > 85) { pump = false; Serial.println("tank full - pump OFF"); }
  if (pump && millis() - pumpWindow > 8000) {
    if (lvl >= levelAtWindow + 3) { pumpWindow = millis(); levelAtWindow = lvl; }     // level is rising: all fine
    else { alarm = true; pump = false; Serial.println("DRY-RUN ALARM: pump on but the level is not rising"); }
  }
  digitalWrite(GREEN_LED, pump);
  if (millis() - lastPrint > 1000) {
    lastPrint = millis();
    Serial.print("level "); Serial.print(lvl, 0); Serial.print(" %  pump "); Serial.println(pump ? "ON" : "OFF");
  }
  delay(100);
}

