  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  servo.attach(SERVO_PIN);
  servo.write(0);
  Serial.begin(9600);
}

void loop() {
  bool hand = digitalRead(IR_PIN) == LOW || digitalRead(PIR_PIN) == HIGH;
  if (hand) {
    openedAt = millis();
    if (!lidOpen) { lidOpen = true; servo.write(90); digitalWrite(GREEN_LED, HIGH); Serial.println("lid OPEN"); }
  }
  if (lidOpen && millis() - openedAt > 3000) {
    lidOpen = false; servo.write(0); digitalWrite(GREEN_LED, LOW); Serial.println("lid closed");
    lastMeasure = 0;                                         // measure the fill level right after closing
  }
  if (!lidOpen && millis() - lastMeasure > 600) {            // the sensor only sees the rubbish with the lid shut
    lastMeasure = millis();
    float cm = distCm();
    bool nowFull = cm > 0 && cm < 8;
    if (nowFull != full) { full = nowFull; Serial.println(full ? "bin FULL - please empty" : "bin has room again"); }
    digitalWrite(RED_LED, full);
  }
  delay(20);
}

