int Z1[3] = {150, 100, 60};
int Z2[3] = {100, 60, 40};
int Z3[3] = {50, 30, 20};
int preset = 0, level = 0;
unsigned long lastBeep = 0;

void setup() {
  usBegin();
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
  Serial.println("preset 1: zones 150 / 100 / 50 cm");
}

void loop() {
  if (pressed()) {
    preset = (preset + 1) % 3;
    Serial.print("preset "); Serial.print(preset + 1); Serial.print(": zones ");
    Serial.print(Z1[preset]); Serial.print(" / "); Serial.print(Z2[preset]); Serial.print(" / "); Serial.print(Z3[preset]); Serial.println(" cm");
  }
  float cm = distCm();
  if (cm < 0) cm = 999;
  int now = 0;
  if (cm < Z1[preset]) now = 1;
  if (cm < Z2[preset]) now = 2;
  if (cm < Z3[preset]) now = 3;
  if (now != level) {
    level = now;
    Serial.print("[t="); Serial.print(millis() / 1000); Serial.print(" s] ");
    Serial.print(cm, 0); Serial.print(" cm -> ");
    Serial.println(level == 0 ? "clear" : (level == 1 ? "zone 1: NOTICE" : (level == 2 ? "zone 2: WARNING" : "zone 3: ALARM")));
  }
  digitalWrite(GREEN_LED, level == 0 ? HIGH : (level == 1 ? (millis() / 400) % 2 : LOW));
  if (level == 0 || level == 1) { digitalWrite(RED_LED, LOW); noTone(BUZZER); }
  if (level == 2) {
    digitalWrite(RED_LED, (millis() / 300) % 2);
    if (millis() - lastBeep > 700) { lastBeep = millis(); tone(BUZZER, 1500, 100); }
  }
  if (level == 3) {
    digitalWrite(RED_LED, HIGH);
    tone(BUZZER, (millis() / 200) % 2 ? 1800 : 1100);
  }
  delay(40);
}

// ---- Circuit (Kit 4) ----
// SG90 servo: signal -> D6, red -> 5V, brown -> GND
// VL53L0X: VIN 5V, GND, SDA -> A4, SCL -> A5 (I2C address 0x29)
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
#define SERVO_PIN 6
#define BTN1 2

#include <Servo.h>
Servo servo;
#include <Wire.h>
#include <Adafruit_VL53L0X.h>
Adafruit_VL53L0X tof;

int tofMm() {                              // distance in mm (-1 = out of range)
  VL53L0X_RangingMeasurementData_t m;
  tof.rangingTest(&m, false);
  if (m.RangeStatus == 4) return -1;
  return m.RangeMilliMeter;
}
void tofBegin() {
  if (!tof.begin()) { Serial.println("VL53L0X not found - check SDA/SCL"); while (true) { } }
}
int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

void calibrate() {
  float n = 0, sx = 0, sy = 0, sxy = 0, sxx = 0;
  Serial.println("angle,mm");
  for (int a = 0; a <= 180; a += 15) {
    servo.write(a);
    delay(500);                                              // settle
    long sum = 0; int k = 0;
    for (int i = 0; i < 5; i++) { int m = tofMm(); if (m >= 0) { sum += m; k++; } delay(10); }
    if (k == 0) { Serial.print(a); Serial.println(",out of range"); continue; }
    float mm = sum / (float)k;
    Serial.print(a); Serial.print(","); Serial.println(mm, 1);
    n++; sx += a; sy += mm; sxy += a * mm; sxx += (float)a * a;
  }
  if (n < 2) { Serial.println("not enough valid points"); return; }
  float slope = (n * sxy - sx * sy) / (n * sxx - sx * sx);
  float intercept = (sy - slope * sx) / n;
  Serial.print("fit: distance = "); Serial.print(slope, 3); Serial.print(" mm/degree x angle + "); Serial.print(intercept, 1); Serial.println(" mm");
  servo.write(90);
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  servo.attach(SERVO_PIN);
  servo.write(90);
  Serial.begin(9600);
  tofBegin();
  Serial.println("press the button to start the calibration sweep");
}

void loop() {
  if (pressed()) calibrate();
}

// ---- Circuit (Kit 4) ----
// PIR HC-SR501: VCC 5V, GND, OUT -> D7 (HIGH while it sees motion)
// TTP223 touch pad: VCC 5V, GND, I/O -> D4 (HIGH while touched)
// Green LED anode -> 220 ohm -> D5 (PWM), cathode -> GND
// Red LED anode -> 220 ohm -> D3, cathode -> GND
#define PIR_PIN 7
#define TOUCH_PIN 4
#define GREEN_LED 5
#define RED_LED 3

int level = 0, lastTouch = LOW;
bool override = false;
unsigned long lastMotion = 0, lastFade = 0, lastPrint = 0;

void setup() {
  pinMode(PIR_PIN, INPUT);
  pinMode(TOUCH_PIN, INPUT);
  pinMode(GREEN_LED, OUTPUT);
  pinMode(RED_LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  if (digitalRead(PIR_PIN) == HIGH) lastMotion = millis();
  int t = digitalRead(TOUCH_PIN);
  if (t == HIGH && lastTouch == LOW) {
    override = !override;
    Serial.println(override ? "override ON - lamp held on" : "override OFF - motion control");
  }
  lastTouch = t;
  analogWrite(RED_LED, override ? 40 : 0);

  bool wantOn = override || (lastMotion > 0 && millis() - lastMotion < 8000);
  if (millis() - lastFade >= 10) {
    lastFade = millis();
    if (wantOn && level < 255) level = min(level + 8, 255);   // quick fade up
    if (!wantOn && level > 0) level--;                        // slow fade down (about 2.5 s)
    analogWrite(GREEN_LED, level);
  }
  if (millis() - lastPrint > 1000) { lastPrint = millis(); Serial.print("lamp "); Serial.print(level * 100 / 255); Serial.println(" %"); }
}

