void point(String what) {
  score++;
  tone(BUZZER, 2200, 40);
  Serial.print("+1 "); Serial.print(what); Serial.print("  score "); Serial.println(score);
}

void setup() {
  usBegin();
  pinMode(IR_PIN, INPUT);
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
  Serial.println("press the button to start (15 s)");
}

void loop() {
  if (!playing) {
    if (pressed()) {
      playing = true; score = 0; startMs = millis(); handNear = false; lastIr = digitalRead(IR_PIN);
      digitalWrite(GREEN_LED, HIGH); digitalWrite(RED_LED, LOW);
      Serial.println("GO!");
    }
    return;
  }
  int ir = digitalRead(IR_PIN);
  if (lastIr == HIGH && ir == LOW) point("IR swipe");
  lastIr = ir;
  float cm = distCm();
  bool near = cm > 0 && cm < 25;
  if (near && !handNear) point("ultrasonic hand");
  handNear = near;
  if (millis() - startMs >= 15000) {
    playing = false;
    digitalWrite(GREEN_LED, LOW); digitalWrite(RED_LED, HIGH);
    if (score > best) best = score;
    Serial.print("TIME! score "); Serial.print(score); Serial.print("   best "); Serial.println(best);
    for (int i = 0; i < min(score, 10); i++) { tone(BUZZER, 1500, 100); delay(220); }
    digitalWrite(RED_LED, LOW);
    Serial.println("press the button to play again");
  }
  delay(10);
}

