bool doorOpen = false, alarm = false;
unsigned long authUntil = 0, openedAt = 0, lastAjar = 0;
unsigned long flips[4];
int nFlips = 0;

void raise(String why) {
  if (!alarm) { alarm = true; Serial.print("ALARM: "); Serial.println(why); }
}

void setup() {
  pinMode(HALL_PIN, INPUT_PULLUP);
  pinMode(PIR_PIN, INPUT);
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(RED_LED, OUTPUT);
  Serial.begin(9600);
  doorOpen = digitalRead(HALL_PIN) == HIGH;
  Serial.println("door monitor running");
}

void loop() {
  bool open = digitalRead(HALL_PIN) == HIGH;                // magnet away = door open
  bool authorised = millis() < authUntil;
  if (open != doorOpen) {
    doorOpen = open;
    for (int i = 0; i < 3; i++) flips[i] = flips[i + 1];    // remember the last 4 changes
    flips[3] = millis();
    if (nFlips < 4) nFlips++;
    if (open) {
      openedAt = millis();
      if (!authorised) raise("door forced open");
      else Serial.println("door opened (authorised)");
    } else Serial.println("door closed");
    if (nFlips == 4 && millis() - flips[0] < 2000) raise("tamper pattern - door rattled");
  }
  if (doorOpen && !authorised && digitalRead(PIR_PIN) == HIGH) raise("movement at an unauthorised open door");
  if (doorOpen && authorised && millis() - openedAt > 10000 && millis() - lastAjar > 2000) {
    lastAjar = millis();
    tone(BUZZER, 1200, 150);
    digitalWrite(RED_LED, HIGH); delay(150); digitalWrite(RED_LED, LOW);
    Serial.println("door AJAR - please close it");
  }
  if (pressed()) {
    if (alarm) {
      if (doorOpen) Serial.println("close the door first");
      else { alarm = false; nFlips = 0; noTone(BUZZER); digitalWrite(RED_LED, LOW); Serial.println("alarm reset"); }
    } else {
      authUntil = millis() + 10000;
      Serial.println("AUTHORISED: you have 10 s to open the door");
    }
  }
  if (alarm) {
    tone(BUZZER, (millis() / 250) % 2 ? 1700 : 1000);
    digitalWrite(RED_LED, (millis() / 150) % 2);
  }
}

// ---- Circuit (Kit 4) ----
// HC-SR04: VCC 5V, GND, TRIG -> D9, ECHO -> D10
// VL53L0X: VIN 5V, GND, SDA -> A4, SCL -> A5 (I2C address 0x29)
// IR obstacle sensor: VCC 5V, GND, OUT -> D8 (LOW when something is in front)
// Green LED anode -> 220 ohm -> D5 (PWM), cathode -> GND
// Red LED anode -> 220 ohm -> D3, cathode -> GND
#define TRIG 9
#define ECHO 10
#define IR_PIN 8
#define GREEN_LED 5
#define RED_LED 3

float distCm() {                           // HC-SR04: 10 us trigger pulse, echo time / 58 = cm (-1 = no echo)
  digitalWrite(TRIG, LOW); delayMicroseconds(2);
  digitalWrite(TRIG, HIGH); delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long us = pulseIn(ECHO, HIGH, 30000);
  if (us == 0) return -1;
  return us / 58.2;
}
void usBegin() { pinMode(TRIG, OUTPUT); pinMode(ECHO, INPUT); }
#include <Wire.h>
#include <Adafruit_VL53L0X.h>
Adafruit_VL53L0X tof;

int tofMm() {                              // distance in mm (-1 = out of range)
  VL53L0X_RangingMeasurementData_t m;
  tof.rangingTest(&m, false);
  if (m.RangeStatus == 4) return -1;
  return m.RangeMilliMeter;
}
void tofBegin() {
  if (!tof.begin()) { Serial.println("VL53L0X not found - check SDA/SCL"); while (true) { } }
}

unsigned long lastPrint = 0;

void setup() {
  usBegin();
  pinMode(IR_PIN, INPUT);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
  tofBegin();
}

void loop() {
  float us = distCm();
  int mm = tofMm();
  bool usOk = us > 2 && us < 400;
  bool tofOk = mm >= 0 && mm < 1200;
  bool irNear = digitalRead(IR_PIN) == LOW;                  // the IR module only sees about 30 cm
  float est = -1;
  int conf = 0;                                              // 0 low, 1 medium, 2 high

  if (usOk && tofOk) {
    float t = mm / 10.0;
    float diff = t > us ? t - us : us - t;
    float big = t > us ? t : us;
    if (diff <= 0.1 * big + 1) { est = (t * 2 + us) / 3; conf = 2; }   // agree: favour the laser
    else { est = t; conf = 1; }                                       // disagree: trust the laser
  } else if (tofOk) { est = mm / 10.0; conf = 1; }
  else if (usOk) { est = us; conf = 1; }

  if (irNear && est > 50) conf = 0;                          // IR sees something close but the range says far
  if (!irNear && est >= 0 && est < 10) conf = min(conf, 1);  // very close but IR sees nothing

  digitalWrite(GREEN_LED, conf >= 1);
  digitalWrite(RED_LED, conf <= 1);
  if (millis() - lastPrint > 500) {
    lastPrint = millis();
    Serial.print("US "); Serial.print(usOk ? us : -1, 1); Serial.print(" cm | ToF "); Serial.print(tofOk ? mm / 10.0 : -1, 1);
    Serial.print(" cm | IR "); Serial.print(irNear ? "near" : "clear");
    Serial.print(" -> "); Serial.print(est, 1); Serial.print(" cm, confidence ");
    Serial.println(conf == 2 ? "HIGH" : (conf == 1 ? "MEDIUM" : "LOW"));
  }
  delay(50);
}

// ---- Circuit (Kit 4) ----
// HC-SR04: VCC 5V, GND, TRIG -> D9, ECHO -> D10
// TCRT5000: VCC 5V, GND, DO -> D13 (HIGH over a dark surface / no surface), AO -> A0 (higher = darker)
// Passive piezo buzzer + -> D11, - -> GND (drive it with tone())
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// Green LED anode -> 220 ohm -> D5 (PWM), cathode -> GND
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
#define TRIG 9
#define ECHO 10
#define LINE_DO 13
#define LINE_AO A0
#define BUZZER 11
#define RED_LED 3
#define GREEN_LED 5
#define BTN1 2

float distCm() {                           // HC-SR04: 10 us trigger pulse, echo time / 58 = cm (-1 = no echo)
  digitalWrite(TRIG, LOW); delayMicroseconds(2);
  digitalWrite(TRIG, HIGH); delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long us = pulseIn(ECHO, HIGH, 30000);
  if (us == 0) return -1;
  return us / 58.2;
}
void usBegin() { pinMode(TRIG, OUTPUT); pinMode(ECHO, INPUT); }
int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

bool mute = false;
unsigned long lastBeep = 0, lastBeat = 0, lastPrint = 0;

void setup() {
  usBegin();
  pinMode(LINE_DO, INPUT);
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  if (pressed()) { mute = !mute; Serial.println(mute ? "obstacle beeps muted" : "obstacle beeps on"); }
  bool drop = digitalRead(LINE_DO) == HIGH;                  // no floor reflection under the cane tip
  float cm = distCm();
  if (cm < 0) cm = 400;

  if (drop) {
    digitalWrite(RED_LED, HIGH);
    tone(BUZZER, (millis() / 150) % 2 ? 700 : 500);          // low warbling alarm: unmistakable
    if (millis() - lastPrint > 700) { lastPrint = millis(); Serial.println("DROP-OFF AHEAD!"); }
    return;
  }
  digitalWrite(RED_LED, cm < 40);
  if (cm < 150 && !mute) {
    int gap = map((int)cm, 10, 150, 100, 900);
    if (millis() - lastBeep >= constrain(gap, 100, 900)) { lastBeep = millis(); tone(BUZZER, 1800, 60); }
  } else noTone(BUZZER);
  if (millis() - lastBeat > 2000) { lastBeat = millis(); digitalWrite(GREEN_LED, HIGH); }   // heartbeat blink
  if (millis() - lastBeat > 100) digitalWrite(GREEN_LED, LOW);
  if (millis() - lastPrint > 700 && cm < 150) { lastPrint = millis(); Serial.print("obstacle at "); Serial.print(cm, 0); Serial.println(" cm"); }
  delay(20);
}
